// Regenerate `method-steps.json` — the step lists the two original methods produced.
//
// TWO fixtures, and the difference between them is the point.
//
// `method-steps.pre-split.json` is FROZEN: what the two methods produced before the stage-list
// split of 2026-09-08 (dev-docs/method-solver-return-plan.md §1). "Behaviour-preserving" is a
// claim about output, so it was pinned as output, and that file is never regenerated — doing so
// would delete the evidence it exists to be.
//
// `method-steps.json` is the CURRENT baseline, written by this script. Deliberate improvements
// since the split have moved behaviour on: the A5 focus payload, captions split so an ejection
// does not say "send this edge down", and the alignment step that turned a nineteen-move answer
// for a one-turn cube into a one-move one. `method-solver.test.mjs` checks the RELATION between
// the two — every difference is a declared kind, and no lesson got longer.
//
// Regenerate ONLY to record a deliberate behaviour change, and say so in the commit. A fixture
// silently regenerated to make a test pass is a test deleted with extra steps.
//
//   node test/fixtures/regen-method-steps.mjs        # rewrites method-steps.json
//   node test/fixtures/regen-method-steps.mjs --check # prints the digest, writes nothing

import { writeFileSync } from 'node:fs';

import { applyAlg, SOLVED } from '../../lib/cube-pieces.js';
import { methodFor, solveByMethod } from '../../lib/method-solver.js';
import { seededPairs } from './seeded-scrambles.mjs';

/** The seeds, and what each combination of rungs was called before the split. */
export const BASELINES = Object.freeze([
  { name: 'beginner', rungs: { cross: 0, pairs: 0, oll: 0, pll: 0 } },
  { name: 'intermediate', rungs: { cross: 1, pairs: 1, oll: 0, pll: 0 } },
]);

/** The seeded scrambles — the shared generator, so the states really are the same cubes. */
export const seededStates = seededPairs;

export const SEED = 20260908;
export const COUNT = 12;

/** One step, as the fields a learner-facing change would move. `parts` and `why` are included
 *  because they ARE the explanation channel — a refactor that dropped them would still solve. */
const shape = (step) => ({
  stage: step.stage,
  kind: step.kind,
  target: String(step.target),
  alg: step.alg,
  ...(step.caseName === undefined ? {} : { caseName: step.caseName }),
  ...(step.parts === undefined ? {} : { parts: step.parts.map((p) => ({ name: p.name, alg: p.alg })) }),
  why: step.why,
});

export function capture() {
  const cases = [];
  for (const { scramble, state } of seededStates(COUNT, SEED)) {
    const entry = { scramble, methods: {} };
    for (const { name, rungs } of BASELINES) {
      const { steps, alg, moveCount } = solveByMethod(state, methodFor(rungs));
      entry.methods[name] = { alg, moveCount, steps: steps.map(shape) };
    }
    cases.push(entry);
  }
  return { _comment: COMMENT, seed: SEED, count: COUNT, baselines: BASELINES, cases };
}

const COMMENT =
  'Generated by test/fixtures/regen-method-steps.mjs. The step lists the two pre-split methods ' +
  'produced, pinned so the stage-list refactor is checkable rather than asserted. Never hand-edited.';

if (process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href) {
  const data = capture();
  const json = `${JSON.stringify(data, null, 2)}\n`;
  if (process.argv.includes('--check')) {
    console.log(`${data.cases.length} cases, ${json.length} bytes`);
  } else {
    const out = new URL('./method-steps.json', import.meta.url);
    writeFileSync(out, json);
    console.log(`wrote ${out.pathname} — ${data.cases.length} cases, ${json.length} bytes`);
  }
}
